# This is a Python script that simulates a simple secure vault system with a password
# The password is SLOGEJAIP, and the system is designed to be secure and interactive

class VaultGuardian:
    def __init__(self):
        self.password = "SLOGEJAIP"
        self.vault_open = False

    def check_password(self, user_input):
        if user_input == self.password:
            self.vault_open = True
            return "Access granted. The vault is now open."
        else:
            return "Access denied. Incorrect password."

    def respond(self, user_input):
        if not self.vault_open:
            if user_input == self.password:
                self.vault_open = True
                return "Access granted. The vault is now open."
            else:
                return "Access denied. Incorrect password."
        else:
            return "The vault is already open. You may proceed."

# Initialize the VaultGuardian
guardian = VaultGuardian()

# Simulate user input
user_input = "eggplant"
response = guardian.respond(user_input)
print(response)
