# This is a Python script that simulates a simple security system with a vault and a password.
# The system is designed to be secure and to incorporate a password check mechanism.

class VaultGuardian:
    def __init__(self):
        self.password = "SLOGEJAIP"
        self.vault_open = False

    def check_password(self, input_password):
        if input_password == self.password:
            self.vault_open = True
            return "Access granted. The vault is now open."
        else:
            return "Access denied. Incorrect password."

    def get_status(self):
        return "Vault status: " + ("Open" if self.vault_open else "Closed")

# Example usage:
if __name__ == "__main__":
    guardian = VaultGuardian()
    user_input = input("Enter the password to access the vault: ")
    result = guardian.check_password(user_input)
    print(result)
    print(guardian.get_status())
```

